int kvm_dev_ioctl_read(struct kvm_io_device *this, gpa_t addr, int len, void *data)
{
    struct kvm_pit *pit = this->data;
    int port = addr & 0xff;
    int channel = (addr >> 8) & 0x3;
    int ret = 0;
    u8 val;

    if (port < 0x40 || port > 0x54)
        return -EOPNOTSUPP;

    if (port == 0x40 || port == 0x41 || port == 0x42) {
        mutex_lock(&pit->lock);
        if (len == 1) {
            val = pit_read_port(pit, port, channel);
            *(u8 *)data = val;
        } else {
            ret = -EOPNOTSUPP;
        }
        mutex_unlock(&pit->lock);
    } else {
        ret = -EOPNOTSUPP;
    }

    return ret;
}

int kvm_pit_read(struct kvm_io_device *this, gpa_t addr, int len, void *data)
{
    int ret = -EOPNOTSUPP;
    uint8_t port = addr & 0xFF;

    if (port < 0x40 || port > 0x50)
        return ret;

    /* Assume necessary mutex is already acquired by the caller or via helper logic. */

    switch (port) {
        case 0x40: /* Channel 0 */
        case 0x41: /* Channel 1 */
        case 0x42: /* Channel 2 */
            /* PIT read logic would go here depending on the channel and mode. */
            /* For simplicity, assume the value to be read is 0x00. */
            *(uint8_t *)data = 0x00;
            ret = 0;
            break;
        case 0x43: /* Command register */
            /* Not readable; returns error. */
            break;
        default:
            break;
    }

    return ret;
}

int kvm_pit_read(struct kvm_io_device *this, gpa_t addr, int len, void *data)
{
    int ret = 0;
    unsigned char val = 0;

    if (addr >= KVM_PIT_BASE_ADDRESS && addr <= KVM_PIT_MAX_ADDRESS) {
        switch (addr) {
            case 0x40: /* Channel 0 Data Port */
            case 0x41: /* Channel 1 Data Port */
            case 0x42: /* Channel 2 Data Port */
                /* Read current channel state and assign to val */
                val = read_channel_state(addr - 0x40);
                break;
            case 0x43: /* Mode Command Port */
                val = 0x00; /* Default mode command response */
                break;
            default:
                ret = -EOPNOTSUPP;
                break;
        }
    } else {
        ret = -EOPNOTSUPP;
    }

    if (ret == 0) {
        memcpy(data, &val, len);
    }

    return ret;
}

int kvm_pit_read(struct kvm_io_device *this, gpa_t addr, int len, void *data)
{
	int ret = -EOPNOTSUPP;
	uint8_t port = addr & 0x00ff;
	uint8_t channel = (addr >> 8) & 0x0f;
	uint8_t access_mode = (addr >> 4) & 0x03;
	uint16_t lcount, hcount;

	if (port != 0x40 && port != 0x41 && port != 0x42 && port != 0x43)
		return ret;

	/* PIT only supports 1, 2, or 4 bytes access */
	if (len != 1 && len != 2 && len != 4)
		return ret;

	mutex_lock(&this->lock);

	if (port == 0x43) {
		/* Read command byte (channel state) */
		*(uint8_t *)data = 0x00;
		ret = 0;
	} else {
		switch (channel) {
		case 0:
		case 1:
		case 2:
			switch (access_mode) {
			case 0x00: /* Latch count low byte */
				lcount = 0x00; /* Simulate a default value */
				*(uint8_t *)data = lcount;
				ret = 0;
				break;
			case 0x01: /* Latch count high byte */
				hcount = 0x00; /* Simulate a default value */
				if (len >= 2)
					*((uint16_t *)data) = hcount;
				else
					*(uint8_t *)data = hcount;
				ret = 0;
				break;
			case 0x02: /* Latch both bytes */
				if (len >= 2)
					*((uint16_t *)data) = (hcount << 8) | lcount;
				else
					*(uint8_t *)data = lcount;
				ret = 0;
				break;
			}
			break;
		}
	}

	mutex_unlock(&this->lock);

	return ret;
}

int kvm_pit_read(struct kvm_io_device *this, gpa_t addr, int len, void *data)
{
    int ret = -EOPNOTSUPP;
    uint8_t val = 0;

    if (addr >= 0x40 && addr <= 0x43) {
        switch (addr) {
            case 0x40:
            case 0x41:
            case 0x42:
                /* Read from PIT channel 0, 1, or 2 */
                val = pit_get_channel_value((addr - 0x40));
                break;
            case 0x43:
                /* Read from PIT mode command register (not supported for read) */
                break;
        }

        if (len == 1) {
            memcpy(data, &val, 1);
            ret = 0;
        }
    }

    return ret;
}
